"""A short ordinary Word research passport and writing plan, not thesis chapters."""
from pathlib import Path
import re,json
from docx.shared import Cm,Pt
from thesis_format import new_document,add_footnote

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'documents';OUT.mkdir(exist_ok=True)
passport=(ROOT/'writing/RESEARCH_PASSPORT.md').read_text()
brief=(ROOT/'writing/CHAPTER_EVIDENCE_MAP.md').read_text()
def plain(s):return re.sub(r'[*`]+','',s).strip()
def block(name):
    match=re.search(r'^## '+re.escape(name)+r'\n(.*?)(?=^## |\Z)',passport,re.M|re.S)
    return match.group(1).strip()
def prose(s):
    for value in s.split('\n\n'):
        value=plain(value)
        if value:d.add_paragraph(value)
def label(name,value):
    p=d.add_paragraph();p.add_run(name+(' ' if name.endswith('.') else ': ')).bold=True;p.add_run(value);return p
def heading(text):return d.add_paragraph(text,style='Thesis Section')
def rows(name):
    data=[]
    for line in block(name).splitlines():
        if line.startswith('|'):
            cells=[plain(c)for c in line.strip('|').split('|')]
            if not all(re.fullmatch(r'[-: ]+',v)for v in cells):data.append(cells)
    return data[1:]

d=new_document()
d.add_paragraph('Основа дипломного исследования',style='Title')
p=d.add_paragraph('Автомобильная торговля Китая и ЕС\n26 октября 2026 года');p.alignment=1;p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.space_after=Pt(10)
prose('Исследовательская база подготовлена для начала написания диплома. Документ фиксирует тему, цель, задачи, аналитические положения, структуру и правила работы с доказательствами. Данные и модели рассчитаны; тексты трёх глав, окончательные иллюстрации и единый диплом составляют следующий этап.')

heading('Тема и исследовательская постановка')
label('Тема',plain(block('Тема').split('\n\n')[0]).rstrip('.')+'.')
prose(block('Проблема и центральный вопрос'))
prose(block('Объект, предмет и цель'))
label('Границы исследования','Январь 2021 — декабрь 2025 года; 27 стран ЕС; три кода новых легковых автомобилей китайского происхождения: BEV, бензиновые PHEV и бензиновые HEV. Национальность марки и страна конечных продаж отдельно не наблюдаются. Изменения политики 2026 года относятся к последующему контексту.')

heading('Задачи и методы')
for number,task,sections,result in rows('Задачи и место их решения'):
    p=d.add_paragraph();p.add_run(number+'. '+task+'. ').bold=False;p.add_run('Параграфы '+sections+'. ').italic=True;p.add_run('Результат: '+result+'.')
p=label('Информационная база','Eurostat Comext, DS-045409: количество автомобилей и стоимость в евро. Коды 87038010, 87036010, 87034010. Сопоставление происхождений и агрегатов проверено; восстановленные нули отделены от явно опубликованных наблюдений.')
add_footnote(d,p,'Eurostat. International trade in goods — detailed data: reference metadata; Comext DS-045409. Использована сохранённая выгрузка от 26.10.2026 за январь 2021 — декабрь 2025 года. Определения и контрольные суммы зафиксированы в исследовательских материалах.')
p=label('Методы','Сравнительный анализ литературы, структурные доли, средняя таможенная стоимость единицы, HHI и эффективное число стран, симметричные разложения, усреднение порядков замены по Шепли, разделение продолжающих и новых положительных стран, PPML с постоянными эффектами и эквивалентная взвешенная модель долей. Количество и стоимость оцениваются отдельно; интервалы показаны через HAC и блочные повторные оценки.')
add_footnote(d,p,'Santos Silva J. M. C., Tenreyro S. The Log of Gravity // Review of Economics and Statistics. 2006. Vol. 88. No. 4. P. 641–658. DOI 10.1162/rest.88.4.641. Shorrocks A. F. Decomposition procedures for distributional analysis: a unified framework based on the Shapley value // Journal of Economic Inequality. 2013. Vol. 11. P. 99–126. DOI 10.1007/s10888-011-9214-z. Методы атрибутируются литературе; собственными являются расчёты случая.')

heading('Аналитические положения и результаты проверки')
prose('Положения сформулированы после анализа данных и используются для организации изложения. Они не являются независимо пререгистрированными прогнозами. Неподтверждённое положение сохраняется в работе.')
for ident,statement,criterion,status in rows('Аналитические положения и их фактический статус'):
    first=label(ident+'.',statement+'.');first.paragraph_format.keep_with_next=True
    middle=label('Проверка.',criterion+'.');middle.paragraph_format.keep_with_next=True
    last=label('Статус.',status+'.');last.paragraph_format.keep_together=True
prose('Предпочтительная условная оценка количества HEV в окончательной фазе также велика: множитель 29,788; HAC(12) [6,729; 131,874], блочный интервал [6,938; 249,773]. Ширина интервалов и чувствительность к спецификации обязательны для интерпретации. Эти множители не являются оценкой причинного эффекта пошлины.')

heading('Собственный вклад и практическое применение')
prose(block('Собственный вклад'))
prose(block('Практическая значимость'))
p=d.add_paragraph('В теоретической главе требуется различать пограничную оценку стоимости и розничную цену. Для этого дополнительно получены и целевым образом прочитаны открытые полные тексты Amiti, Redding, Weinstein (2019) и NBER-версия Cavallo с соавторами (2019); журнальная публикация второй работы датирована 2021 годом. Глубина чтения каждой версии записана отдельно.')
add_footnote(d,p,'Amiti M., Redding S. J., Weinstein D. E. The Impact of the 2018 Tariffs on Prices and Welfare // Journal of Economic Perspectives. 2019. Vol. 33. No. 4. P. 187–210. Целевое чтение с. 187–189. Cavallo A., Gopinath G., Neiman B., Tang J. Tariff Passthrough at the Border and at the Store: Evidence from US Trade Policy. NBER Working Paper 26396. 2019. Прочитаны аннотация и введение, основной текст с. 1–4. Журнальная версия: American Economic Review: Insights. 2021. Vol. 3. No. 1. P. 19–34.')

heading('Структура диплома')
prose('Сохраняется согласованная последовательность: первая глава теоретическая, вторая аналитическая, третья рекомендательная. План включает 14 параграфов. Рабочий ориентир — около 60–70 страниц основного текста; это распределение объёма для написания, а не утверждение о нормативе кафедры.')
purposes={
'1.1':'Разграничить производственное происхождение, марку, место оформления и конечный спрос; определить технологии и единицу анализа.',
'1.2':'Раскрыть каналы торговых барьеров и промышленной политики и условия изменения количества, цен и состава поставок.',
'1.3':'Сопоставить товарное переключение, изменение качества, географии и интенсивности существующих направлений с доступными показателями.',
'1.4':'Прямо сравнить ближайшие работы, сформулировать собственный вопрос и пределы претензии на новизну.',
'2.1':'Дать официальную хронологию и объяснить коды, период, наблюдаемость, нули и состав модельной выборки.',
'2.2':'Определить показатели и разложения, затем раскрыть экономический смысл модели, контролей и интервалов.',
'2.3':'Исследовать количество, стоимость и товарный состав на одних и тех же границах статистической корзины.',
'2.4':'Объяснить концентрацию через технологии, товарные веса, внутритехнологическую географию и продолжающие либо новые страны.',
'2.5':'Показать предпочтительные оценки, предшествующую динамику, географические контрасты и фиксированные чувствительности.',
'2.6':'Свести наблюдаемые изменения и условные оценки, ответить на исследовательский вопрос и определить основания рекомендаций.',
'3.1':'Предложить паспорт совместного мониторинга технологий, количества, стоимости и концентрации.',
'3.2':'Разграничить статистическую концентрацию оформления и реальную логистическую зависимость; раскрыть сценарные допущения.',
'3.3':'Определить, как учитывать несколько технологий и целей при обсуждении торговых и промышленных мер.',
'3.4':'Составить матрицу адресатов, оснований, дополнительных данных, контроля и ограничений рекомендаций.'}
for line in brief.splitlines():
    if line.startswith('## Глава '):
        p=d.add_paragraph(plain(line[3:]),style='Thesis Section')
    elif line.startswith('### '):
        title=plain(line[4:]);ident=title.split()[0]
        if ident in purposes:
            p=d.add_paragraph();p.add_run(title+'. ').bold=True;p.add_run(purposes[ident])
label('Введение и заключение.','Во введении использовать единый паспорт, а окончательную редакцию выполнить после глав. В заключении ответить на восемь задач без новых результатов и источников.')
label('Приложения.','Классификация CN8/TARIC; аудит и запросы; все спецификации и интервалы; численные проверки; формулы разложений; паспорт мониторинга. В основном тексте выделяется предпочтительная расширенная модель.')

heading('Оформление и организация написания')
prose('Основа оформления — последняя согласованная версия диплома и курсовая Наумова. Формат A4; Times New Roman 12; полуторный интервал; первая строка 1,25 см; выравнивание по ширине; поля слева 2,5 см, справа 1 см, сверху и снизу 2 см. Заголовки глав 14, параграфов 12, полужирные. Номер страницы справа внизу; титульный лист итогового диплома без видимого номера. Все тексты и заголовки чёрные, активные гиперссылки отсутствуют.')
prose('Ссылки оформляются обычными подстрочными сносками, 10 пунктов, одинарный интервал. Название рисунка помещается под изображением, номер и название таблицы — над таблицей. Внутри графика заголовок не дублируется. Формулы при сборке оформляются редактируемыми средствами Word и проверяются после отображения.')
prose('Писать последовательно по параграфам, начиная с главы 1. Для каждого параграфа подготовлена карта вопроса, аргумента, источников, расчётов и границ вывода. Числа берутся из реестра доказательств, а страницы ссылок — из реально прочитанной версии. Итоговая библиография содержит только использованные и проверенные источники.')
prose('Рабочий реестр включает 31 научную и учебную работу и 10 официальных источников. По одной близкой публикации Joule полный текст не получен; по Head–Mayer проверены метаданные и аннотация. Это отражается в глубине допустимого пересказа. Вспомогательная запись с непроверенным годом исключена из будущей библиографии до уточнения. Главы можно начинать с имеющейся доказательной базой.')
prose('Перед началом текста повторно проверены сохранённые исходные данные, соответствие модели контрольным суммам, результаты 18 расширенных спецификаций, 398 блочных повторных оценок и 16 разложений концентрации. Проверки пройдены. Этот документ является подготовительной основой; готовым дипломом он не обозначается.')

path=OUT/'auto_thesis_writing_base.docx';d.save(path)
print(json.dumps({'path':str(path),'paragraphs':len(d.paragraphs),'native_footnotes':3,'chapter_texts_written':False},ensure_ascii=False))
